import {SHOPS,DISTRICTS,COLORS,COMPLETE,INCOMPLETE,KEEP,newGame,groups,groupIncome,income,holdings,claimPlots,beginBuild,canPlace,placeShop,finishYear,nextYear,emptyOffer,evaluateOffer,trade,rankings,validSave} from './engine.mjs';
import {createGameAudio} from './audio.mjs';
import {createTrading} from './trading.mjs';
import {zodiacImages} from './zodiac.mjs';
const $=s=>document.querySelector(s),KEY='vietnamtown-save-v1';
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=validSave(saved)?saved:newGame();}catch{state=newGame();}
let language='vi';try{language=localStorage.getItem('vietnamtown-language')||'vi';}catch{}
const tr=(en,vi)=>language==='vi'?vi:en;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`${n.toLocaleString('en-US')} <span class="money-symbol">đ</span>`;
const SPRITES=['coffee','banhmi','pho','flowers','tailor','grocery'];
const LANDMARKS=['tan-dinh','ben-thanh','thao-dien','cho-lon','binh-thanh','phu-nhuan'];
const ZODIAC=[['Tỵ','Snake','snake'],['Ngọ','Horse','horse'],['Mùi','Goat','goat'],['Thân','Monkey','monkey'],['Dậu','Rooster','rooster'],['Tuất','Dog','dog']];
const TOKEN_COLORS=['#39a883','#eec353','#dc6f57','#7fb5cf'];
let view='play',selectedShop=null,selectedLot=null,chosen=[],partner=1,lastFocus=null,toastTimer=null;
let freshLots=[],zoom=1,pan={x:0,y:0},fitScale=1,drag=null,suppressClick=false,controlsCollapsed=false;
let observedPhase='',renderedYear=state.year,phaseTimer=null,phaseDelay=null,cashFrame=null,payout=null,freshTimer=null;
const reducedMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const gameAudio=createGameAudio({onChange:()=>updateSoundButton()});
const trading=createTrading({getState:()=>state,tr,sprite,token,modal,closeModal,onChanged:()=>changed(),playSound,onTrading:v=>gameAudio.setTrading(v)});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast(tr('Progress cannot be saved. Keep this tab open.','Không lưu được tiến độ. Hãy giữ thẻ này mở.'));}}
function changed(){save();render();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function modal(title,content,eyebrow='VIETNAM TOWN'){dismissPhase();if(trading.isOpen())trading.cancel();lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-header"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2></div><button class="close" aria-label="${tr('Close dialog','Đóng')}" data-action="close">×</button></div><div class="modal-body">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){trading.cancel();$('#modal').close();lastFocus?.focus?.();}
function sprite(kind,name,cls='',extra=''){return `<img class="pixel ${cls}" src="/assets/${kind}/${name}.png" alt="" draggable="false" ${extra}>`;}
function zodiacSprite(index,cls=''){return `<img class="pixel ${cls}" src="${zodiacImages[ZODIAC[index][2]]}" alt="${ZODIAC[index][0]}" draggable="false">`;}
function token(player,cls=''){return sprite('materials','token-'+player,'owner-token '+cls);}
function lotLabel(l){return `${tr('Plot','Lô')} ${l.id+1}, ${DISTRICTS[Math.floor(l.id/12)]}, ${l.owner===null?tr('unclaimed','chưa có chủ'):l.owner===0?tr('yours','của bạn'):state.players[l.owner].name}${l.shop===null?'':', '+SHOPS[l.shop].name}`;}
function phaseName(p=state.phase){return ({receive:tr('Receive','Nhận lộc'),trade:tr('Trade','Thương lượng'),build:tr('Build','Mở tiệm'),income:tr('Payday','Thu tiền'),ended:tr('Finale','Tổng kết')})[p];}
function board(){return DISTRICTS.map((name,b)=>`<section class="district district-${b}" aria-label="${name}"><div class="landmark">${sprite('landmarks',LANDMARKS[b])}</div><div class="district-sign"><span>${String(b+1).padStart(2,'0')}</span><strong>${name}</strong></div><div class="district-grid">${state.lots.slice(b*12,b*12+12).map(l=>{const offered=state.pending.includes(l.id),picked=chosen.includes(l.id),shop=l.shop===null?null:SHOPS[l.shop],valid=state.phase==='build'&&selectedShop!==null&&canPlace(state,0,l.id,selectedShop);return `<button data-lot="${l.id}" class="lot ${l.owner!==null?'owned':''} ${l.owner===0?'mine':''} ${offered?'offered':''} ${picked?'picked':''} ${selectedLot===l.id?'inspected':''} ${shop?'built':''} ${valid?'buildable':''} ${freshLots.includes(l.id)?'fresh':''} ${state.phase==='build'&&l.owner===0&&l.shop===null?'ready-plot':''}" aria-label="${lotLabel(l)}" aria-pressed="${picked||selectedLot===l.id}" style="--piece-delay:${Math.max(0,Math.min(12,freshLots.indexOf(l.id)))*40}ms"><span class="plot-number">${l.id+1}</span>${shop?sprite('shops',SPRITES[l.shop],'built-shop'):'<span class="plot-edge"></span>'}${l.owner!==null?token(l.owner):picked?token(0,'draft-token'):''}${valid?sprite('shops',SPRITES[selectedShop],'build-ghost'):''}${shop?`<span class="plot-target">${shop.size}</span>`:''}</button>`;}).join('')}</div></section>`).join('');}
function calendar(){return `<section class="calendar" aria-label="${tr('Zodiac year wheel','Vòng năm con giáp')}"><div class="year-wheel">${sprite('materials','calendar-wheel','wheel-art')}<div class="year-pointer" style="--angle:${(state.year-1)*60}deg"><span></span></div>${ZODIAC.map((z,i)=>{const a=i*Math.PI/3;return `<button class="year-node ${i+1===state.year?'current':''} ${i+1<state.year?'past':''}" style="left:${50+35*Math.sin(a)}%;top:${50-35*Math.cos(a)}%" data-action="year-info" data-year="${i+1}" aria-label="${tr('Year','Năm')} ${i+1}, ${z[0]}"><span>${z[0]}</span><small>${i+1}</small></button>`;}).join('')}<div class="year-center"><small>${tr('YEAR','NĂM')}</small><strong>${state.year}</strong><span>${ZODIAC[state.year-1][0]}</span></div></div></section>`;}
function playerCard(){return `<div class="player-rail">${state.players.map((p,i)=>`<div class="player-pocket ${i===0?'your-pocket':''}" style="--player-color:${TOKEN_COLORS[i]}"><button class="pocket-main" data-action="player-info" data-player="${i}" aria-label="${i===0?tr('Your inventory','Kho của bạn'):p.name}, ${p.cash} đ"><span class="pocket-token">${token(i)}<b>${i===0?tr('YOU','BẠN'):p.name.toUpperCase()}</b></span><span class="wallet"><strong data-wallet="${i}">${money(p.cash)}</strong><small>+${income(state,i)} đ / ${tr('yr','năm')}</small></span></button><div class="pocket-inventory" aria-label="${tr('Unused shop pieces','Mảnh tiệm chưa dùng')}">${p.tiles.map((n,s)=>n?`<button data-action="glance-shop" data-player="${i}" data-shop-index="${s}" title="${SHOPS[s].name} ×${n}" aria-label="${p.name}, ${SHOPS[s].name}, ${n}">${sprite('shops',SPRITES[s])}<b>${n}</b></button>`:'').join('')||`<span>${tr('Empty rack','Hết mảnh tiệm')}</span>`}<button class="inventory-more" data-action="player-info" data-player="${i}" aria-label="${tr('View inventory','Xem kho')}">⋯</button></div></div>`).join('')}</div>`;}
function phaseCard(){let title,body,action;switch(state.phase){
case'receive':title=tr('Claim your corner.','Chọn góc phố của bạn.');body=tr(`Put counters on ${state.draftCount} glowing plots.`,`Đặt dấu lên ${state.draftCount} lô đang sáng.`);action=`<div class="claim-tools"><button data-drag-token="0" class="counter-stack" aria-label="${tr('Drag your counter onto a glowing plot','Kéo dấu của bạn lên lô sáng')}">${[0,1,2,3].map(n=>token(0,`stack-${n}`)).join('')}</button><div class="address-strip">${state.pending.map(id=>`<button data-lot="${id}" class="address-slip ${chosen.includes(id)?'selected':''}" aria-pressed="${chosen.includes(id)}">${id+1}</button>`).join('')}</div><button class="primary" data-action="claim" ${chosen.length!==state.draftCount?'disabled':''}>${tr('Keep','Giữ')} ${chosen.length}/${state.draftCount} ✓</button></div>`;break;
case'trade':title=tr('Who has your missing piece?','Ai đang giữ mảnh bạn cần?');body=tr('Tap a neighbor, their shop piece, or their plot.','Chạm hàng xóm, mảnh tiệm hoặc lô của họ để trả giá.');action=`<button class="primary" data-action="trade">${tr('Let’s bargain','Đi trả giá')} ⇄</button><button class="secondary" data-action="build">${tr('Start building','Bắt đầu xây')} →</button>`;break;
case'build':title=tr('Open for business.','Khai trương thôi!');body=tr('Choose a piece below, or tap your plot for a quick build menu.','Chọn mảnh bên dưới, hoặc chạm lô của bạn để mở menu xây.');action=`<span class="payday-preview">${tr('Next payday','Sắp thu')} <b>${income(state,0)} đ</b></span><button class="primary" data-action="collect">${tr('Finish & collect','Xong rồi, thu tiền')} →</button>`;break;
case'income':title=tr('A good year in the neighborhood.','Một năm buôn may bán đắt.');body=tr(`Your shops brought in ${state.lastIncome[0]} đ.`,`Các tiệm mang về ${state.lastIncome[0]} đ.`);action=`<button class="primary" data-action="next">${tr('Welcome year','Sang năm')} ${state.year+1} →</button><button class="secondary" data-action="income">${tr('Earnings','Sổ thu')}</button>`;break;
default:title=tr('Six years. One thriving town.','Sáu năm, phố mình đổi khác.');body=tr('Time to see who grew the biggest fortune.','Cùng xem ai có nhiều tiền nhất nhé.');action=`<button class="primary" data-action="results">${tr('Final standings','Xem kết quả')} ★</button>`;}
return `<section class="turn-scroll"><div class="phase-heading"><span class="phase-medal">${{receive:'01',trade:'02',build:'03',income:'04',ended:'★'}[state.phase]}</span><div><small>${phaseName()}</small><h2>${title}</h2></div><button class="replay-guide" data-action="guide" aria-label="${tr('Replay phase guide','Xem lại hướng dẫn bước này')}">?</button></div><p>${body}</p><div class="phase-actions">${action}</div></section>`;}
function hand(){return `<section class="tile-rack" aria-label="${tr('Your shop pieces','Mảnh tiệm của bạn')}"><div class="rack-label"><span>${tr('YOUR SHOPS','TIỆM CỦA BẠN')}</span><button data-action="businesses">${tr('Ledger','Sổ tiệm')} ↗</button></div><div class="shop-tray">${SHOPS.map((s,i)=>`<button class="shop-piece ${selectedShop===i?'active':''} ${state.players[0].tiles[i]===0?'depleted':''}" data-shop="${i}" data-drag-shop="${i}" aria-pressed="${selectedShop===i}" aria-label="${s.name}, ${state.players[0].tiles[i]} ${tr('pieces','mảnh')}, ${s.size} ${tr('adjacent for','liền kề được')} ${COMPLETE[s.size]} đ"><span class="piece-count">×${state.players[0].tiles[i]}</span>${sprite('shops',SPRITES[i])}<strong>${s.name}</strong><small><b>${s.size} ${tr('tiles','mảnh')}</b> → ${COMPLETE[s.size]} đ</small></button>`).join('')}</div><div class="rack-hint">${tr('Connect matching shops along shared edges. Income shown per year.','Ghép tiệm cùng loại, cùng chủ, chung cạnh. Tiền tính mỗi năm.')}</div></section>`;}
function selection(){if(selectedLot===null)return '';const l=state.lots[selectedLot],g=l.shop===null?null:groups(state,l.owner).find(g=>g.lots.includes(l.id));
const build=state.phase==='build'&&l.owner===0?`<div class="quick-build"><small>${l.shop===null?tr('OPEN HERE','MỞ TIỆM TẠI ĐÂY'):tr('CONTINUE THIS BUSINESS','MỞ RỘNG TIỆM NÀY')}</small><div>${SHOPS.map((s,i)=>{if(!state.players[0].tiles[i]||(l.shop!==null&&i!==l.shop))return '';return `<button data-action="quick-build" data-id="${l.id}" data-index="${i}" aria-label="${l.shop===null?tr('Build','Xây'):tr('Select','Chọn')} ${s.name}">${sprite('shops',SPRITES[i])}<strong>${s.name}</strong><small>×${state.players[0].tiles[i]} · ${s.size} → ${COMPLETE[s.size]} đ</small></button>`;}).join('')||`<span>${tr('No matching pieces in your rack.','Kho chưa có mảnh phù hợp.')}</span>`}</div></div>`:'';
return `<div class="plot-inspector"><div class="inspector-top"><span class="inspector-address">${l.id+1}</span><div><strong>${DISTRICTS[Math.floor(l.id/12)]}</strong><small>${l.owner===null?tr('Unclaimed','Chưa có chủ'):l.owner===0?tr('Your plot','Lô của bạn'):state.players[l.owner].name}${l.shop!==null?' · '+SHOPS[l.shop].name:''}</small>${g?`<small>${g.size}/${SHOPS[g.shop].size} ${tr('connected','liền kề')} · ${groupIncome(g.shop,g.size)} đ/${tr('yr','năm')}</small>`:''}</div>${state.phase==='trade'&&l.owner!==null&&l.owner!==0?`<button class="primary" data-action="trade-lot" data-id="${l.id}">${tr('Bargain','Trả giá')} ⇄</button>`:''}<button class="close" data-action="deselect" aria-label="${tr('Close','Đóng')}">×</button></div>${build}</div>`;}
function streetScene(){return `<div class="map-terrain" aria-hidden="true">${sprite('city','saigon-city-board','city-background')}<span class="street-name street-top">LÊ VĂN DUYỆT</span><span class="street-name street-mid">NGUYỄN TRÃI</span><span class="street-name street-bottom">VÕ VĂN KIỆT</span><span class="river-name">SÔNG SÀI GÒN</span><div class="vehicle ninja-ride">${sprite('life','ninja-lead')}</div><div class="vehicle ninja-return">${sprite('life','ninja-lead')}</div><div class="vehicle city-bus">${sprite('life','city-bus')}</div><div class="walker crossing-one"><span></span></div><div class="walker crossing-two"><span></span></div><div class="walker crossing-three"><span></span></div><div class="map-plaque">SÀI GÒN<small>BUÔN CÓ BẠN · BÁN CÓ PHƯỜNG</small></div></div>`;}
function render(){document.documentElement.lang=language;document.body.dataset.phase=state.phase;document.body.classList.toggle('notebook-open',view==='research');updateHeader();gameAudio.setPhase(state.phase);if(view==='research'){dismissPhase();renderResearch();return;}
const oldTerrain=$('.map-terrain'),oldYear=renderedYear;
$('#app').innerHTML=`${playerCard()}<div class="play-stage"><section class="board-area" aria-label="${tr('Neighborhood game board','Bàn chơi khu phố')}"><div class="board-frame"><div class="map-viewport" tabindex="0" aria-label="${tr('Game map. Drag streets to pan, plus and minus to zoom.','Bản đồ. Kéo đường phố để di chuyển, cộng trừ để thu phóng.')}"><div class="game-world">${streetScene()}${board()}</div></div></div><div class="map-controls"><button data-action="zoom-out" aria-label="${tr('Zoom out','Thu nhỏ')}">−</button><button data-action="zoom-reset" class="zoom-label" aria-label="${tr('Fit map','Vừa bản đồ')}">${Math.round(zoom*100)}%</button><button data-action="zoom-in" aria-label="${tr('Zoom in','Phóng to')}">+</button><span>${tr('Drag the streets to explore','Kéo đường phố để xem quanh')}</span><button class="collapse-controls" data-action="collapse" aria-expanded="${!controlsCollapsed}">${controlsCollapsed?tr('Show controls','Hiện điều khiển'):tr('More map','Mở rộng bản đồ')} ${controlsCollapsed?'⌃':'⌄'}</button></div>${selection()}</section></div><div class="command-dock ${controlsCollapsed?'collapsed':''}">${calendar()}${phaseCard()}${hand()}</div><footer class="game-footer"><span>${tr('Saved on this browser · You + 3 computer neighbors','Đã lưu trên trình duyệt · Bạn + 3 hàng xóm máy')}</span><button data-action="history">${tr('Neighborhood journal','Nhật ký khu phố')} ↗</button></footer>`;
if(oldTerrain) $('.map-terrain').replaceWith(oldTerrain);
document.body.classList.toggle('controls-collapsed',controlsCollapsed);
requestAnimationFrame(()=>{fitMap();updateGuides();animateWallets();if(oldYear!==state.year)animateYear(oldYear);});renderedYear=state.year;
const key=state.year+':'+state.phase;if(observedPhase!==key){observedPhase=key;dismissPhase();if(!['income','ended'].includes(state.phase)){clearTimeout(phaseDelay);phaseDelay=setTimeout(()=>showPhase(),oldYear===state.year?200:1100);}}
}
function updateHeader(){const p=$('#phase-ribbon');if(p)p.innerHTML=`<b>${tr('YEAR','NĂM')} ${state.year} / 6</b><span>${phaseName()}</span>`;$('#language-toggle').textContent=language==='vi'?'VI · EN':'EN · VI';updateSoundButton();}
function fitMap(){const vp=$('.map-viewport'),world=$('.game-world');if(!vp||!world)return;fitScale=Math.min(vp.clientWidth/1100,vp.clientHeight/730);const sx=1100*fitScale*zoom,sy=730*fitScale*zoom;pan.x=Math.max(-Math.max(0,(sx-vp.clientWidth)/2),Math.min(Math.max(0,(sx-vp.clientWidth)/2),pan.x));pan.y=Math.max(-Math.max(0,(sy-vp.clientHeight)/2),Math.min(Math.max(0,(sy-vp.clientHeight)/2),pan.y));world.style.transform=`translate(calc(-50% + ${pan.x}px),calc(-50% + ${pan.y}px)) scale(${fitScale*zoom})`;$('.zoom-label').textContent=Math.round(zoom*100)+'%';}
function updateGuides(){document.querySelectorAll('.guide-target').forEach(e=>e.classList.remove('guide-target'));const selector={receive:chosen.length===state.draftCount?'[data-action="claim"]':'.counter-stack, .lot.offered:not(.picked), .address-slip:not(.selected)',trade:'.player-pocket:not(.your-pocket) .pocket-main',build:selectedShop===null?'.shop-piece:not(.depleted)':'.lot.buildable',income:'[data-action="next"]',ended:'[data-action="results"]'}[state.phase];document.querySelectorAll(selector).forEach(e=>e.classList.add('guide-target'));}
function showPhase(){clearTimeout(phaseDelay);if(view!=='play'||$('#modal').open)return;clearTimeout(phaseTimer);const descriptions={receive:[`Choose ${state.draftCount} of these addresses. Place your green counters, then keep your selection.`,`Chọn ${state.draftCount} địa chỉ bên dưới. Đặt dấu xanh, rồi bấm Giữ để bắt đầu thương lượng.`],trade:['Tap a neighbor or one of their plots. Put your offer on the table and bargain for the missing pieces.','Chạm hàng xóm hoặc lô của họ. Đặt tài sản lên bàn rồi trả giá để lấy mảnh còn thiếu.'],build:['Pick a shop from your rack and tap your empty plot. Or tap your plot first to open the quick build menu.','Chọn mảnh tiệm rồi chạm lô trống của bạn. Hoặc chạm lô trước để mở menu xây nhanh.'],income:['Every business has paid its owner. Turn the year wheel when you are ready.','Mỗi tiệm đã trả tiền cho chủ. Khi sẵn sàng, bấm Sang năm để quay vòng năm mới.'],ended:['The final payday is here. Open the standings to find the winner.','Đã đến lần thu tiền cuối cùng. Mở kết quả để xem ai thắng nhé.']};
$('#phase-cue').innerHTML=`<section class="phase-announcement"><button data-action="dismiss-phase" class="close" aria-label="${tr('Dismiss guide','Đóng hướng dẫn')}">×</button><small>${tr('YEAR','NĂM')} ${state.year} · ${ZODIAC[state.year-1][0]}</small><h2>${phaseName()}</h2><p>${tr(...descriptions[state.phase])}</p>${state.phase==='receive'?`<div class="deal-reels">${state.pending.map((id,i)=>`<span style="--deal-delay:${i*90}ms"><b>${id+1}</b></span>`).join('')}</div>`:state.phase==='build'?`<div class="cue-sprites">${sprite('shops','coffee')}${sprite('shops','banhmi')}${sprite('shops','pho')}</div>`:state.phase==='trade'?`<div class="cue-tokens">${token(0)}<b>⇄</b>${token(1)}</div>`:''}<button class="primary" data-action="dismiss-phase">${tr('Let’s go','Bắt đầu nào')} →</button><div class="cue-countdown"></div></section>`;$('#phase-cue').classList.add('show');playSound('phase');phaseTimer=setTimeout(dismissPhase,6500);}
function dismissPhase(){clearTimeout(phaseTimer);clearTimeout(phaseDelay);$('#phase-cue')?.classList.remove('show');}
function animateYear(from){if(reducedMotion())return;const pointer=$('.year-pointer'),wheel=$('.wheel-art');pointer?.animate([{transform:`rotate(${(from-1)*60}deg)`},{transform:`rotate(${(state.year-1)*60}deg)`}],{duration:1300,easing:'cubic-bezier(.2,.8,.2,1)'});wheel?.animate([{transform:'rotate(-60deg)',filter:'brightness(1.5)'},{transform:'rotate(0deg)',filter:'brightness(1)'}],{duration:1300,easing:'cubic-bezier(.2,.8,.2,1)'});$('.year-node.current')?.animate([{boxShadow:'0 0 0 12px #ffe6a8'},{boxShadow:'0 0 0 2px #f2d583'}],{duration:1800});playSound('year');}
function clickLot(id){dismissPhase();if(state.phase==='receive'){if(!state.pending.includes(id)){selectedLot=id;render();return;}selectedLot=null;if(chosen.includes(id))chosen=chosen.filter(x=>x!==id);else if(chosen.length<state.draftCount){chosen.push(id);freshLots=[id];playSound('place');}else toast(tr(`Keep ${state.draftCount} addresses. Lift a counter first.`,`Chỉ giữ ${state.draftCount} địa chỉ. Nhấc một dấu trước nhé.`));render();scheduleFreshClear();return;}if(state.phase==='build'&&selectedShop!==null&&canPlace(state,0,id,selectedShop)){buildPiece(id,selectedShop);return;}selectedLot=id;render();}
function buildPiece(id,shop){const before=income(state,0);placeShop(state,id,shop);selectedLot=null;freshLots=[id];playSound('build');if(!state.players[0].tiles[shop])selectedShop=null;changed();scheduleFreshClear();const g=groups(state,0).find(g=>g.lots.includes(id));toast(`${SHOPS[shop].name} · ${g.size}/${SHOPS[shop].size} ${tr('connected','liền kề')} · +${income(state,0)-before} đ/${tr('yr','năm')}`);return {id,shop,annualIncome:income(state,0)};}
function scheduleFreshClear(){clearTimeout(freshTimer);freshTimer=setTimeout(()=>{freshLots=[];document.querySelectorAll('.fresh').forEach(el=>el.classList.remove('fresh'));},1800);}
function updateSoundButton(){const settings=gameAudio.getSettings(),b=$('#sound-toggle'),m=$('#music-toggle');if(!b||!m)return;b.classList.toggle('sound-on',settings.sfx);b.setAttribute('aria-pressed',String(settings.sfx));b.title=tr('Tap sounds: ','Âm thanh chạm: ')+(settings.sfx?tr('on','bật'):tr('off','tắt'));b.setAttribute('aria-label',b.title);m.classList.toggle('sound-on',settings.music);m.setAttribute('aria-pressed',String(settings.music));m.textContent=(settings.music?'♫ ':'♫ ')+tr('Lofi','Lofi')+(settings.music?' ✓':'');m.title=tr('Lo-fi music: ','Nhạc lofi: ')+(settings.music?tr('on','bật'):tr('off','tắt'));}
function playSound(kind='tap'){gameAudio.play(kind);}
function animateWallets(){if(!payout)return;cancelAnimationFrame(cashFrame);const p=payout,elapsed=performance.now()-p.start,t=reducedMotion()?1:Math.min(1,Math.max(0,(elapsed-350)/1600)),ease=1-Math.pow(1-t,3);state.players.forEach((player,i)=>{const el=$(`[data-wallet="${i}"]`);if(el){el.innerHTML=money(Math.round(p.before[i]+(player.cash-p.before[i])*ease));el.classList.toggle('wallet-counting',t<1);}});if(t<1)cashFrame=requestAnimationFrame(animateWallets);else payout=null;}
function celebratePayday(before){dismissPhase();payout={before,start:performance.now()};playSound('income');animateWallets();const fx=$('#effects');fx.innerHTML='';if(!reducedMotion())state.players.forEach((p,i)=>{const to=$(`[data-wallet="${i}"]`)?.getBoundingClientRect();if(!to)return;const sources=holdings(state,i).filter(l=>l.shop!==null).slice(0,5);sources.forEach((l,n)=>{const r=$(`[data-lot="${l.id}"]`)?.getBoundingClientRect();if(!r)return;const el=document.createElement('div');el.className='flying-note';el.innerHTML=sprite('life','game-banknote');fx.append(el);const sx=r.x+r.width/2,sy=r.y+r.height/2,tx=to.x+to.width/2,ty=to.y+to.height/2;const anim=el.animate([{transform:`translate(${sx}px,${sy}px) rotate(-18deg) scale(.6)`,opacity:0},{offset:.18,transform:`translate(${sx}px,${sy-40}px) rotate(8deg) scale(1.1)`,opacity:1},{transform:`translate(${tx}px,${ty}px) rotate(0) scale(.5)`,opacity:0}],{duration:1500,delay:n*100+i*70,easing:'cubic-bezier(.3,.1,.4,1)',fill:'both'});anim.onfinish=()=>el.remove();});});
const banner=document.createElement('div');banner.className='payday-banner';banner.innerHTML=`<small>${tr('YEAR-END PAYDAY','THU TIỀN CUỐI NĂM')}</small><strong>+${state.lastIncome[0]} đ</strong><span>${tr('Your shops are paying off','Buôn may bán đắt!')}</span>`;fx.append(banner);setTimeout(()=>banner.remove(),3200);}
function openTrade(prefillLot=null,prefillShop=null){if(state.phase!=='trade')return toast(tr('Trading opens after you claim your addresses.','Thương lượng mở sau khi bạn nhận mặt bằng.'));if(prefillLot!==null)partner=state.lots[prefillLot].owner;trading.open(partner,prefillLot,prefillShop);}
function playerInfo(id){const p=state.players[id];modal(id===0?tr('Your inventory.','Kho của bạn.'):`${p.name} · ${tr('Inventory','Tài sản')}`,`<div class="neighbor-summary">${token(p.id)}<strong>${money(p.cash)}</strong><span>${holdings(state,id).length} ${tr('plots','lô')} · ${income(state,id)} đ/${tr('yr','năm')}</span></div><p>${tr('Tap a shop to start a trade for that piece.','Chạm mảnh tiệm để bắt đầu đổi lấy mảnh đó.')}</p><div class="neighbor-shop-grid">${SHOPS.map((s,i)=>`<button data-action="glance-shop" data-player="${id}" data-shop-index="${i}" ${p.tiles[i]===0?'disabled':''}>${sprite('shops',SPRITES[i])}<strong>${s.name} ×${p.tiles[i]}</strong><small>${s.size} ${tr('tiles','mảnh')} → ${COMPLETE[s.size]} đ</small></button>`).join('')}</div><p class="mini-label">${tr('ADDRESSES','MẶT BẰNG')}</p><div class="neighbor-lots">${holdings(state,id).map(l=>`<button data-action="inspect-player-lot" data-id="${l.id}">${l.shop!==null?sprite('shops',SPRITES[l.shop]):token(id)}<b>${l.id+1}</b></button>`).join('')||tr('None yet.','Chưa có.')}</div>${state.phase==='trade'&&id!==0?`<button class="primary wide" data-action="trade-player" data-player="${id}">${tr('Bargain with','Thương lượng với')} ${p.name} ⇄</button>`:''}${id===0?`<button class="secondary wide" data-action="businesses">${tr('Business ledger','Sổ tiệm')}</button>`:''}`);}
function rules(){modal('Build a street worth coming back to.',`<p>You and three computer neighbors have six years to grow a business community. The most cash after the sixth payday wins.</p><ol><li><strong>Receive.</strong> Choose from your offered addresses, then receive shop tiles. You keep ${KEEP.join(', ')} plots in years 1–6. Tiles: 5 in year one, then 4 each year.</li><li><strong>Trade.</strong> Make as many deals as you like. Exchange cash, empty plots, built plots, and unused shop tiles. Both sides must accept; our computer neighbors assess each proposal.</li><li><strong>Build.</strong> Place any number of tiles on your own empty plots for free. Drag a shop from your rack to your empty address, or select the shop and tap its plot. Placement is permanent. Unused tiles carry over.</li><li><strong>Collect.</strong> Every business pays every year, even one just opened. The game ends after year six’s income.</li></ol><h3>What counts as one business?</h3><p>Tiles of the same shop type and owner connect along shared edges inside one block. Diagonals and streets don’t connect. Match the shop’s target size to complete it.</p><table><thead><tr><th>Tiles</th><th>Incomplete income</th><th>Complete income</th></tr></thead><tbody>${[1,2,3,4,5,6].map(n=>`<tr><td>${n}</td><td>${n===6?'—':INCOMPLETE[n]+' đ'}</td><td>${n>=3?COMPLETE[n]+' đ':'—'}</td></tr>`).join('')}</tbody></table><p class="rules-note">Example: three connected Cà phê tiles earn 50 đ every year. Three connected Phở tiles earn 40 đ; add a fourth to earn 80 đ. Separate businesses are paid separately.</p><h3>Small but useful details</h3><ul><li>You start with 50 đ. All amounts are fictional đồng; these are game values.</li><li>No building costs, rent, interest, or end-game resale value. Tied cash is broken by most shop tiles on the board; an exact tie is shared.</li><li>A group larger than its target pays as complete target-sized sets plus an incomplete remainder. You can keep growing along the block.</li><li>Switching to Build closes trading for that year. Check your deals first.</li><li>Progress saves only in this browser. These are local computer opponents, not online players. Cash is visible in this adaptation.</li></ul><button class="primary wide" data-action="close">Back to the neighborhood</button>`,'HOW TO PLAY');}
function incomeModal(){modal(tr('This year’s earnings.','Sổ thu năm nay.'),`<p>${tr('Every business has paid its owner.','Mỗi tiệm đã trả tiền cho chủ.')}</p>${state.players.map((p,i)=>`<div class="score-row">${token(i)}<span>${i===0?tr('You','Bạn'):escape(p.name)}</span><strong>+${money(state.lastIncome[i]??0)}</strong><span class="muted">${tr('Total','Tổng')} ${p.cash} đ</span></div>`).join('')}<div class="modal-actions"><button class="primary" data-action="${state.phase==='ended'?'results':'next'}">${state.phase==='ended'?tr('Final standings','Xem kết quả'):tr('Begin year ','Sang năm ')+(state.year+1)} →</button></div>`,phaseName('income'));}
function results(){const ranked=rankings(state),top=ranked[0].cash,topTiles=state.lots.filter(l=>l.owner===ranked[0].id&&l.shop!==null).length,winners=ranked.filter(p=>p.cash===top&&state.lots.filter(l=>l.owner===p.id&&l.shop!==null).length===topTiles);modal(winners.length>1?tr('A shared victory.','Cùng chia chiến thắng.'):ranked[0].id===0?tr('This neighborhood is yours!','Phố này là của bạn!'):`${escape(ranked[0].name)} ${tr('wins!','chiến thắng!')}`,`<p>${tr('The final payday is counted.','Đã tính lần thu tiền cuối cùng.')}</p>${ranked.map((p,i)=>`<div class="score-row ${winners.some(w=>w.id===p.id)?'winner':''}"><span>${i+1}</span>${token(p.id)}<span>${p.id===0?tr('You','Bạn'):escape(p.name)}</span><strong>${money(p.cash)}</strong></div>`).join('')}<p class="muted">${tr(`You completed ${state.trades} trades. Your businesses earned ${income(state,0)} đ in the last year. Cash ties are broken by placed shop pieces.`,`Bạn đã chốt ${state.trades} giao dịch. Các tiệm thu ${income(state,0)} đ ở năm cuối. Nếu bằng tiền, ai đã xây nhiều mảnh hơn xếp trên.`)}</p><div class="modal-actions"><button class="secondary" data-action="close">${tr('Explore the town','Ngắm khu phố')}</button><button class="primary" data-action="new">${tr('Play again','Chơi ván mới')}</button></div>`,tr('SIX YEARS · FINAL STANDINGS','SÁU NĂM · KẾT QUẢ'));}
function businesses(){const g=groups(state,0);modal(tr('Your businesses.','Sổ tiệm của bạn.'),g.length?`<table><thead><tr><th>${tr('Shop','Tiệm')}</th><th>${tr('Plots','Lô')}</th><th>${tr('Connected / target','Liền kề / cần đủ')}</th><th>${tr('Per year','Mỗi năm')}</th></tr></thead><tbody>${g.map(b=>`<tr><td>${SHOPS[b.shop].name}</td><td>${b.lots.map(x=>x+1).join(', ')}</td><td>${b.size} / ${SHOPS[b.shop].size}${b.size>=SHOPS[b.shop].size?' ✓':''}</td><td>${groupIncome(b.shop,b.size)} đ</td></tr>`).join('')}</tbody></table><strong>${tr('Total','Tổng')}: ${income(state,0)} đ / ${tr('year','năm')}</strong>`:`<p>${tr('No shops open yet. Tap one of your empty plots during Build.','Chưa có tiệm. Chạm lô trống của bạn ở bước Mở tiệm để bắt đầu.')}</p>`);}
function renderResearch(){$('#app').innerHTML=`<article class="research"><p class="eyebrow">THE DESIGN NOTEBOOK</p><h1>From Chinatown to Vietnam Town.</h1><p class="research-intro">Keep the negotiation. Give it a neighborhood that feels like home. This prototype translates Chinatown’s business-building puzzle into an original, fictional map of Sài Gòn.</p><div class="info-chips"><span>6 years</span><span>72 addresses</span><span>6 Vietnamese businesses</span><span>You + 3 computer neighbors</span></div><div class="research-grid"><section class="research-card"><p class="eyebrow">01 · THE ORIGINAL</p><h2>The deal is the game.</h2><p>Karsten Hartwig’s <em>Chinatown</em> is a negotiation game for 3–5 players. Over six rounds, players receive building cards and business tiles, trade freely, place shops, and collect income. Cash at the end decides the winner; placed shop tiles break a tie. <a href="https://cdn.1j1ju.com/medias/46/fa/78-chinatown-rulebook.pdf" target="_blank" rel="noopener noreferrer">2014 rulebook ↗</a></p><p>The clever part is uneven value. An address that is forgettable to you might finish somebody else’s business. Random allocations create reasons to negotiate; the neighborhood grid makes those reasons visible.</p><p>Connected, same-owner shops form businesses. A business of its target size earns more, and earlier completion pays off repeatedly.</p></section><section class="research-card"><p class="eyebrow">02 · THE ADAPTATION</p><h2>A familiar kind of commerce.</h2><p>Vietnam Town is about neighborhood livelihoods: coffee houses, food shops, florists, tailors, and corner grocers. The vocabulary, storefront art, and place names carry the setting.</p><p>The six block names draw from places in Hồ Chí Minh City. Their arrangement and street names form a fictional game map. Keeping Chợ Lớn in the town acknowledges the city’s Chinese-Vietnamese commercial heritage.</p><p>Use the same strategic question throughout: <em>“What can we trade so both of our streets work better?”</em></p></section></div><h2>Translate the mechanics, not just the labels.</h2><table><thead><tr><th>Chinatown mechanic</th><th>Vietnam Town interpretation</th><th>What it gives the player</th></tr></thead><tbody><tr><td>Building ownership cards</td><td>Numbered shop addresses in six neighborhood blocks</td><td>A visible reason to negotiate for adjacent space</td></tr><tr><td>Business tiles</td><td>Cà phê, Bánh mì, Phở, Tiệm hoa, Tiệm may, Tạp hóa</td><td>Distinct trades with target sizes from 3 to 6</td></tr><tr><td>Open negotiation</td><td>A two-sided offer of cash, addresses, and shop tiles</td><td>Package deals, counteroffers, and mutual benefit</td></tr><tr><td>Connected shops</td><td>Rows of matching businesses along the same block</td><td>Planning that depends on where other players own space</td></tr><tr><td>Annual income</td><td>Year-end shop earnings in fictional đồng</td><td>A reason to build early and value remaining paydays</td></tr><tr><td>Richest player wins</td><td>Most cash after the sixth year</td><td>A clear ending without extra scoring systems</td></tr></tbody></table><div class="research-grid"><section class="research-card"><p class="eyebrow">03 · PLAYABLE NOW</p><h2>A complete local game.</h2><ul><li>One player and three computer opponents.</li><li>Six full years of address drafting, negotiation, building, and income.</li><li>Arbitrary packages of plots, tiles, and cash, with bot acceptance and cash counteroffers.</li><li>Permanent placement, edge adjacency, ownership changes, income calculation, and final standings.</li><li>Automatic progress saving in this browser, plus a game journal.</li></ul><p><strong>Deliberate changes:</strong> 72 plots instead of the original 85, six shop types instead of twelve, a larger tile supply, adjusted draws, sequential address choices, visible money, and scripted opponents. The original income curve and overflow scoring are retained in fictional đồng units. Bot negotiation is a first way to test the economy; it cannot reproduce human bargaining.</p></section><section class="research-card"><p class="eyebrow">04 · THE NEXT BUILD</p><h2>Bring friends to the table.</h2><ol><li><strong>Playtest the economy.</strong> Check completion rates, rejected deals, and whether all shop types remain useful.</li><li><strong>Add online rooms.</strong> Use authoritative shared game state, visible shop tiles and private cash, simultaneous offers, reconnects, and a ready check before building.</li><li><strong>Make the town come alive.</strong> Expand the Aseprite street-life set with seasonal variants and more shop opening animations.</li><li><strong>Refine the local voice.</strong> Extend the Vietnamese/English game interface to the research notebook and review details with Vietnamese players.</li></ol><p>Keep the visual identity, wording, and map original. A close commercial adaptation would need a separate rights review.</p></section></div><section class="research-card"><p class="eyebrow">THE ASEPRITE ARTBOOK</p><h2>A town built one pixel at a time.</h2><p>The shops, landmarks, counters, ground tiles, and zodiac wheel are original pixel drawings created in Aseprite. Each building has named editable layers for its ground, architecture, fixtures, goods, and details.</p><div class="art-gallery">${SHOPS.map((shop,i)=>`<figure>${sprite('shops',SPRITES[i])}<figcaption>${shop.name}</figcaption></figure>`).join('')}</div><p>Look for phin filters and low stools at the café; a glass baguette cart at the bánh mì shop; a stockpot and soup bowls at the phở kitchen; flower buckets, a dress form and áo dài, and grocer’s sacks and crates.</p><p><a href="https://www.vietnam.travel/things-to-do/secret-art-vietnamese-coffee" target="_blank" rel="noopener noreferrer">Vietnam Tourism: street coffee</a> · <a href="https://vietnam.travel/node/125" target="_blank" rel="noopener noreferrer">The story of phở</a> · <a href="https://www.vietnam.travel/things-to-do/explore-old-quarter-your-way" target="_blank" rel="noopener noreferrer">Neighborhood storefront references</a></p><div class="art-gallery">${DISTRICTS.map((name,i)=>`<figure>${sprite('landmarks',LANDMARKS[i])}<figcaption>${name}</figcaption></figure>`).join('')}</div><p>The landmark silhouettes include Tân Định’s pink church, Bến Thành’s clock tower, a Chợ Lớn market gateway, and the Bà Chiểu market frontage. Thảo Điền and Phú Nhuận are interpretive river-villa and leafy-alley scenes. <a href="https://visithcmc.net/en/news/kham-pha-cho-ben-thanh-diem-den-khong-the-bo-qua-o-tp-ho-chi-minh" target="_blank" rel="noopener noreferrer">HCMC Tourism reference ↗</a></p><h3>Street life, drawn in Aseprite.</h3><p>A helmeted, sun-covered Ninja Lead rider, a bus with a driver and passengers, four-frame walking pedestrians, and a fictional lotus banknote bring the game events into the city.</p><div class="art-gallery street-art-gallery">${['ninja-lead','city-bus','pedestrian','game-banknote'].map(n=>`<figure>${sprite('life',n)}<figcaption>${n.replaceAll('-',' ')}</figcaption></figure>`).join('')}</div><figure class="city-art-preview">${sprite('city','saigon-city-board')}<figcaption>The original city board, with the playable pieces lifted away.</figcaption></figure><div class="art-downloads"><a href="/assets/vietnamtown-aseprite-source.zip" download>Download all layered Aseprite sources</a><a href="/assets/vietnamtown-sprites.zip" download>Download the PNG sprite set</a></div></section><div class="source-links"><a href="https://boardgamegeek.com/boardgame/47/chinatown" target="_blank" rel="noopener noreferrer">Chinatown on BoardGameGeek ↗</a><a href="https://cdn.1j1ju.com/medias/46/fa/78-chinatown-rulebook.pdf" target="_blank" rel="noopener noreferrer">Z-Man Games rulebook (2014, mirrored) ↗</a></div><p class="muted" style="font-size:12px;margin-top:16px">Independent research prototype inspired by Chinatown. No affiliation with its designer or publisher. Original artwork; fictional neighborhood layout. Research checked September 2026.</p><button class="primary" data-action="play">Back to your neighborhood →</button></article>`;}
function act(action,el){switch(action){
case 'close':closeModal();break;
case 'play':view='play';render();window.scrollTo({top:0});break;
case 'research':closeModal();view='research';render();window.scrollTo({top:0});break;
case 'language':language=language==='vi'?'en':'vi';try{localStorage.setItem('vietnamtown-language',language);}catch{}closeModal();dismissPhase();render();break;
case 'rules':if(language==='en')rules();else rulesVietnamese();break;
case 'sound':gameAudio.setSfx(!gameAudio.getSettings().sfx);void gameAudio.unlock().then(()=>playSound());toast(gameAudio.getSettings().sfx?'♪ '+tr('Tap sounds on','Đã bật âm thanh chạm'):tr('Tap sounds off','Đã tắt âm thanh chạm'));break;
case 'music':gameAudio.setMusic(!gameAudio.getSettings().music);void gameAudio.unlock();toast(gameAudio.getSettings().music?'♫ '+tr('Saigon lo-fi · music follows each phase','Sài Gòn lofi · nhạc đổi theo từng bước'):tr('Music off','Đã tắt nhạc'));break;
case 'guide':showPhase();break;
case 'dismiss-phase':dismissPhase();updateGuides();break;
case 'collapse':controlsCollapsed=!controlsCollapsed;render();break;
case 'zoom-in':zoom=Math.min(2.5,Math.round((zoom+.25)*100)/100);fitMap();break;
case 'zoom-out':zoom=Math.max(1,Math.round((zoom-.25)*100)/100);fitMap();break;
case 'zoom-reset':zoom=1;pan={x:0,y:0};fitMap();break;
case 'year-info':{const y=Number(el.dataset.year),z=ZODIAC[y-1];modal(`${tr('Year','Năm')} ${y} · ${z[0]}`,`<div class="zodiac-detail">${zodiacSprite(y-1)}<p>${tr('The year of the '+z[1].toLowerCase()+'.','Năm '+z[0]+'.')}</p></div><p>${y===state.year?tr('Your current year.','Bạn đang ở năm này.'):y<state.year?tr('This year is complete.','Năm này đã qua.'):tr('Finish this year to turn the wheel forward.','Hoàn thành năm hiện tại để quay vòng năm mới.')}</p><div class="year-rewards"><strong>${KEEP[y-1]} <small>${tr('new plots','lô mới')}</small></strong><span>+</span><strong>${y===1?5:4} <small>${tr('shop pieces','mảnh tiệm')}</small></strong></div><p class="rules-note">${tr('Six successive zodiac animals beginning with Snake. This is a game calendar.','Sáu con giáp liên tiếp, bắt đầu từ Tỵ. Đây là lịch riêng của trò chơi.')}</p>`,'VÒNG NĂM CON GIÁP');break;}
case 'player-info':playerInfo(Number(el.dataset.player));break;
case 'glance-shop':{const id=Number(el.dataset.player),shop=Number(el.dataset.shopIndex);if(id===0){closeModal();selectedShop=shop;selectedLot=null;render();if(state.phase!=='build')toast(tr('You can place this during Build.','Bạn có thể đặt mảnh này ở bước Mở tiệm.'));}else if(state.phase==='trade'){partner=id;openTrade(null,shop);}else playerInfo(id);break;}
case 'inspect-player-lot':{const id=Number(el.dataset.id);closeModal();if(state.phase==='trade'&&state.lots[id].owner!==0)openTrade(id);else{selectedLot=id;render();}break;}
case 'trade-player':partner=Number(el.dataset.player);openTrade();break;
case 'claim':{freshLots=[...chosen];claimPlots(state,chosen);chosen=[];selectedLot=null;changed();scheduleFreshClear();playSound('build');toast(tr('Addresses claimed. Your new shop pieces are in the rack.','Đã nhận mặt bằng. Mảnh tiệm mới đã vào kho.'));break;}
case 'trade':openTrade();break;
case 'trade-lot':openTrade(Number(el.dataset.id));break;
case 'build':modal(tr('All deals done?','Chốt hết rồi chứ?'),`<p>${tr('Building closes trading for this year. Shop placement is permanent.','Bắt đầu xây sẽ đóng thương lượng trong năm này. Mảnh tiệm đã đặt sẽ giữ nguyên vị trí.')}</p><div class="modal-actions"><button class="secondary" data-action="close">${tr('Keep bargaining','Trả giá tiếp')}</button><button class="primary" data-action="confirm-build">${tr('Open the shops','Mở tiệm thôi')} →</button></div>`,phaseName('build'));break;
case 'confirm-build':beginBuild(state);selectedLot=null;selectedShop=null;closeModal();changed();break;
case 'quick-build':{const id=Number(el.dataset.id),shop=Number(el.dataset.index);if(state.lots[id].shop===null)buildPiece(id,shop);else{selectedShop=shop;selectedLot=null;render();toast(tr('Tap one of your empty plots beside this business.','Chạm một lô trống của bạn cạnh tiệm này.'));}break;}
case 'place':buildPiece(selectedLot,selectedShop);break;
case 'deselect':selectedLot=null;render();break;
case 'collect':{const possible=holdings(state,0).some(l=>SHOPS.some((_,s)=>canPlace(state,0,l.id,s)));if(possible)modal(tr('Close up for the year?','Nghỉ bán để thu tiền nhé?'),`<p>${tr('You can still build. Keep unused pieces for next year, or open more shops now.','Bạn vẫn còn mảnh có thể xây. Giữ lại cho năm sau, hoặc mở thêm tiệm ngay bây giờ.')}</p><div class="modal-actions"><button class="secondary" data-action="close">${tr('Keep building','Xây tiếp')}</button><button class="primary" data-action="confirm-collect">${tr('Collect income','Thu tiền năm nay')}</button></div>`);else act('confirm-collect');break;}
case 'confirm-collect':{const built=new Set(state.lots.filter(l=>l.shop!==null).map(l=>l.id)),cash=state.players.map(p=>p.cash);finishYear(state);freshLots=state.lots.filter(l=>l.shop!==null&&!built.has(l.id)).map(l=>l.id);selectedLot=null;selectedShop=null;closeModal();changed();scheduleFreshClear();celebratePayday(cash);break;}
case 'income':incomeModal();break;
case 'next':{cancelAnimationFrame(cashFrame);payout=null;$('#effects').innerHTML='';nextYear(state);chosen=[];selectedLot=null;selectedShop=null;closeModal();changed();break;}
case 'results':results();break;
case 'businesses':businesses();break;
case 'history':modal(tr('The neighborhood journal.','Nhật ký khu phố.'),`<ul class="history">${state.logs.map(l=>`<li>${escape(l)}</li>`).join('')}</ul>`);break;
case 'new':modal(tr('Start a new neighborhood?','Bắt đầu khu phố mới?'),`<p>${tr('This replaces the game saved in this browser.','Ván đang lưu trên trình duyệt sẽ được thay thế.')}</p><div class="modal-actions"><button class="secondary" data-action="close">${tr('Keep this game','Giữ ván này')}</button><button class="primary" data-action="confirm-new">${tr('A fresh beginning','Bắt đầu lại')}</button></div>`);break;
case 'confirm-new':cancelAnimationFrame(cashFrame);payout=null;$('#effects').innerHTML='';state=newGame();observedPhase='';selectedLot=null;selectedShop=null;chosen=[];freshLots=[];zoom=1;pan={x:0,y:0};view='play';controlsCollapsed=false;closeModal();changed();break;
}}
function rulesVietnamese(){modal('Buôn có bạn, bán có phường.',`<p>Bạn cùng Linh, Minh và An xây phố qua sáu năm. Sau lần thu tiền thứ sáu, người nhiều tiền nhất thắng.</p><ol><li><strong>Nhận lộc.</strong> Đặt dấu xanh lên số lô được giữ: ${KEEP.join(', ')} lô ở các năm 1–6. Nhận 5 mảnh tiệm ở năm đầu, rồi 4 mảnh mỗi năm sau.</li><li><strong>Thương lượng.</strong> Chạm hàng xóm, lô hoặc mảnh tiệm của họ. Đặt tiền, mảnh và mặt bằng lên bàn để trao đổi. Bớt mảnh bằng cách chạm vào đồ đã đặt lên bàn. Có thể trả giá nhiều lần.</li><li><strong>Mở tiệm.</strong> Chọn mảnh rồi chạm lô trống của bạn, kéo thả mảnh, hoặc chạm lô để mở menu xây nhanh. Xây miễn phí, không thể di chuyển mảnh đã xây. Mảnh chưa dùng giữ cho năm sau.</li><li><strong>Thu tiền.</strong> Tiệm vừa xây cũng có thu nhập. Thu xong thì chuyển năm.</li></ol><h3>Ghép thế nào để có nhiều tiền?</h3><p>Tiệm cùng loại, cùng chủ và chung cạnh trong một khu phố sẽ nối thành một cụm. Qua đường hoặc chéo góc không nối. Đủ số mảnh ghi trên tiệm sẽ được mức thu nhập hoàn chỉnh.</p><table><thead><tr><th>Số mảnh</th><th>Chưa đủ</th><th>Đã đủ</th></tr></thead><tbody>${[1,2,3,4,5,6].map(n=>`<tr><td>${n}</td><td>${INCOMPLETE[n]??'—'} đ</td><td>${n>=3?COMPLETE[n]:'—'} đ</td></tr>`).join('')}</tbody></table><p>Tiền là đơn vị đ giả định trong trò chơi. Nếu bằng tiền, ai đã xây nhiều mảnh hơn xếp trên. Đối thủ máy trả giá theo giá trị tài sản và vị trí liền kề.</p>`,'CÁCH CHƠI');}
function preserveControlFocus(el){if(document.activeElement!==document.body)return;for(const attr of ['data-lot','data-shop','data-action'])if(el.hasAttribute(attr)){document.querySelector(`[${attr}="${el.getAttribute(attr)}"]`)?.focus({preventScroll:true});break;}}
document.addEventListener('click',e=>{if(suppressClick){suppressClick=false;e.preventDefault();return;}const barter=e.target.closest('[data-bargain]');if(barter){trading.handle(barter);return;}const el=e.target.closest('[data-action],[data-lot],[data-shop]');if(!el||el.disabled)return;try{playSound('tap');if(el.dataset.lot!==undefined)clickLot(Number(el.dataset.lot));else if(el.dataset.shop!==undefined){dismissPhase();const shop=Number(el.dataset.shop);selectedShop=selectedShop===shop?null:shop;selectedLot=null;render();if(state.phase!=='build')toast(tr('Keep this piece in mind for Build.','Để dành mảnh này cho bước Mở tiệm nhé.'));else if(state.players[0].tiles[shop]===0)toast(tr('You have none of this piece.','Kho chưa có mảnh tiệm này.'));}else act(el.dataset.action,el);preserveControlFocus(el);}catch(error){toast(error.message);}});
function clearDrop(){document.querySelectorAll('.drop-target').forEach(l=>l.classList.remove('drop-target'));}
function cancelDrag(){drag=null;$('#drag-piece').className='';$('#drag-piece').innerHTML='';document.body.classList.remove('dragging');clearDrop();}
document.addEventListener('pointerdown',e=>{if(e.button!==0||$('#modal').open||e.target.closest('button:not([data-drag-shop]):not([data-drag-token]):not([data-lot])'))return;const shop=e.target.closest('[data-drag-shop]'),counter=e.target.closest('[data-drag-token]'),vp=e.target.closest('.map-viewport');let type=null,index=null;if(shop&&state.phase==='build'&&state.players[0].tiles[Number(shop.dataset.dragShop)]>0){type='shop';index=Number(shop.dataset.dragShop);}else if(counter&&state.phase==='receive'){type='counter';index=0;}else if(vp){type='pan';}if(!type)return;drag={type,index,el:shop||counter||vp,id:e.pointerId,x:e.clientX,y:e.clientY,px:pan.x,py:pan.y,active:false};});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.active&&Math.hypot(dx,dy)<6)return;if(!drag.active){drag.active=true;try{drag.el.setPointerCapture(e.pointerId);}catch{}document.body.classList.add('dragging');if(drag.type==='shop'){selectedShop=drag.index;document.querySelectorAll('.lot').forEach(l=>l.classList.toggle('buildable',canPlace(state,0,Number(l.dataset.lot),drag.index)));}if(drag.type!=='pan'){$('#drag-piece').innerHTML=drag.type==='shop'?sprite('shops',SPRITES[drag.index]):token(0);$('#drag-piece').className='show'+(drag.type==='counter'?' token-drag':'');}}if(e.cancelable)e.preventDefault();if(drag.type==='pan'){pan.x=drag.px+dx;pan.y=drag.py+dy;fitMap();return;}$('#drag-piece').style.left=e.clientX+'px';$('#drag-piece').style.top=e.clientY+'px';clearDrop();const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-lot]');if(target){const id=Number(target.dataset.lot),valid=drag.type==='counter'?state.pending.includes(id):canPlace(state,0,id,drag.index);if(valid)target.classList.add('drop-target');}},{passive:false});
document.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;const ended=drag;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-lot]');cancelDrag();if(!ended.active)return;suppressClick=true;setTimeout(()=>suppressClick=false,250);if(ended.type==='pan')return;try{if(!target){render();return;}const id=Number(target.dataset.lot);if(ended.type==='counter'){if(!state.pending.includes(id))toast('Place your counter on one of the glowing addresses.');else if(chosen.includes(id))toast('You already placed a counter here.');else clickLot(id);}else if(canPlace(state,0,id,ended.index))buildPiece(id,ended.index);else{toast('That shop needs one of your empty addresses.');render();}}catch(error){toast(error.message);render();}});
document.addEventListener('pointercancel',()=>{if(drag?.active){cancelDrag();render();}else cancelDrag();});
window.addEventListener('blur',()=>{if(drag){cancelDrag();render();}});
window.addEventListener('resize',fitMap);
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key==='Escape'){dismissPhase();cancelDrag();selectedShop=null;selectedLot=null;render();}const vp=$('.map-viewport');if(e.target===vp){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','0'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')pan.x+=45;if(e.key==='ArrowRight')pan.x-=45;if(e.key==='ArrowUp')pan.y+=45;if(e.key==='ArrowDown')pan.y-=45;if(e.key==='+')zoom=Math.min(2.5,zoom+.25);if(e.key==='-')zoom=Math.max(1,zoom-.25);if(e.key==='0'){zoom=1;pan={x:0,y:0};}fitMap();}}});

document.addEventListener('change',e=>{if(e.target.matches('[data-bargain-cash]'))trading.cashChanged(e.target);});
$('#modal').addEventListener('cancel',()=>trading.cancel());
$('#modal').addEventListener('close',()=>{if(!$('#modal').open)trading.cancel();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>{const s=gameAudio.getSettings();if(s.sfx||s.music)void gameAudio.unlock();},{passive:true});
$('#phase-cue').addEventListener('pointerenter',()=>clearTimeout(phaseTimer));
$('#phase-cue').addEventListener('focusin',()=>clearTimeout(phaseTimer));
$('#phase-cue').addEventListener('pointerleave',()=>{if($('#phase-cue').classList.contains('show'))phaseTimer=setTimeout(dismissPhase,4500);});
state.logs=state.logs.map(l=>l.replaceAll('million ₫','đ').replaceAll('M₫','đ'));
render();save();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'get_neighborhood_state',description:'Read the local Vietnam Town game: phase, players, plots, shop tiles and offered addresses.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>JSON.parse(JSON.stringify(state))});register({name:'claim_neighborhood_plots',description:'Complete the Receive phase by claiming the required number of offered plots. Plot IDs are zero-based.',inputSchema:{type:'object',properties:{plotIds:{type:'array',items:{type:'integer'},uniqueItems:true}},required:['plotIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{claimPlots(state,input.plotIds);chosen=[];changed();return {phase:state.phase,ownedPlots:holdings(state,0).map(l=>l.id)};}});register({name:'start_neighborhood_build',description:'Close trading for this year and start the Build phase.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{beginBuild(state);selectedShop=null;selectedLot=null;changed();return {phase:state.phase};}});register({name:'place_neighborhood_shop',description:'Permanently place one shop tile on your empty plot during Build. Plot IDs and shop indices are zero-based.',inputSchema:{type:'object',properties:{plotId:{type:'integer'},shopIndex:{type:'integer'}},required:['plotId','shopIndex'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{return buildPiece(input.plotId,input.shopIndex);}});
register({name:'collect_neighborhood_income',description:'Finish building, let computer neighbors build, and collect this year’s business income exactly once.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{act('confirm-collect');return {year:state.year,phase:state.phase,income:state.lastIncome,balances:state.players.map(p=>p.cash)};}});
register({name:'advance_neighborhood_year',description:'After payday, turn the zodiac wheel and receive the next year’s offered addresses and shop pieces.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{act('next');return {year:state.year,phase:state.phase,offeredPlots:state.pending,keep:state.draftCount};}});
const sideSchema={type:'object',properties:{cash:{type:'integer',minimum:0},tiles:{type:'array',items:{type:'integer',minimum:0},minItems:6,maxItems:6},lots:{type:'array',items:{type:'integer',minimum:0,maximum:71},uniqueItems:true}},required:['cash','tiles','lots'],additionalProperties:false};
const offerSchema={type:'object',properties:{partner:{type:'integer',minimum:1,maximum:3},give:sideSchema,take:sideSchema},required:['partner','give','take'],additionalProperties:false};
register({name:'quote_neighborhood_trade',description:'Ask a computer neighbor whether a proposed package of cash, shop tiles, and plots would be accepted, without making the exchange. Plot and shop IDs are zero-based.',inputSchema:offerSchema,annotations:{readOnlyHint:true},execute:input=>evaluateOffer(state,input)});
register({name:'propose_neighborhood_trade',description:'Propose a package of cash, shop tiles, and plots to a computer neighbor. An accepted deal exchanges the selected assets; a rejected deal returns a cash counteroffer without changing assets. Plot and shop IDs are zero-based.',inputSchema:offerSchema,annotations:{readOnlyHint:false},execute:input=>{const result=trade(state,input);if(result.accepted){changed();playSound('deal');}else playSound('reject');return result;}});
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
